function redirect_not_logged_in(){
	window.location.replace(process.env.PL_APP_URL + "/login");
}

(async () => {
	let alerts_response = await fetch(process.env.PL_API_URL + '/alerts', {
	  method: 'GET',
	  headers: {
	    'Content-Type': 'application/json;charset=utf-8'
	  }
	});
	if (alerts_response.ok) {
	  let alerts_result = await alerts_response.json();
	  console.log(alerts_result);
	  console.log('this is from options page');
	  if(alerts_result.length == 0){
	  	window.location.replace(process.env.PL_APP_URL + "/?create_price_alerts=1");
		}
		// if user has previously used PriceLasso and has reinstalled extension
		if(alerts_result.length > 0){
	  	window.location.replace(process.env.PL_APP_URL);
		}
	}
	else {
	  // if user is not logged in
	  if(alerts_response.status == '401') {
	    console.log('401');
	    window.location.replace(process.env.PL_APP_URL + "/register");
	  }
	}
})();